"""Build the reference-matched homepage from the portfolio's shared profile."""
from pathlib import Path
from html import escape as e
import json
from portfolio_layout import navigation, footer

root = Path(__file__).resolve().parents[1]
p = json.loads((root / 'src/profile/profile.json').read_text())
def work_panel(project, i):
    cover = project.get('cover', f'/reference/profile/project-{project.get("image_index", i+1)}-0.png')
    return f'''<article class="work-panel work-tone-{i+1}" id="work-panel-{i+1}"><a class="work-art" href="/projects/{e(project['slug'])}" aria-label="Read {e(project['title'])} case study"><span class="work-art-label">{e(project['tags'].split(' · ')[0])}<span>PROJECT / {i+1:02d}</span></span><div class="work-screen"><img src="{e(cover)}" alt="{e(project['title'])} product interface" loading="lazy"></div><span class="work-art-note">A closer look at the work <span aria-hidden="true">↗</span></span></a><div class="work-caption"><div><h3>{e(project['title'])}</h3><p>{e(project['summary'])}</p></div><a class="work-case" href="/projects/{e(project['slug'])}">View case study <span aria-hidden="true">↗</span></a></div></article>'''

projects = ''.join(work_panel(project, i) for i, project in enumerate(p['projects']))
work_tabs = ''.join(f'''<button class="work-tab" id="work-tab-{i+1}" type="button" data-work-tab="{i+1}"><span class="work-tab-number">{i+1:02d}</span><span class="work-tab-copy"><span class="work-tab-category">{e(project['tags'].split(' · ')[0])}</span><span class="work-tab-title">{e(project['title'])}</span></span><span class="work-tab-arrow" aria-hidden="true">↗</span></button>''' for i, project in enumerate(p['projects']))
gallery = ''.join(f'''<button class="detail-card tilt" type="button" data-image="{e(project.get('detail_image', f'/reference/profile/project-{project.get("image_index", i+1)}-1.png'))}" data-title="{e(project['title'])}" aria-label="Enlarge {e(project['title'])} design detail"><img src="{e(project.get('detail_image', f'/reference/profile/project-{project.get("image_index", i+1)}-1.png'))}" alt="{e(project['title'])} design detail" loading="lazy"><span>0{i+1} / {e(project['title'])} <span aria-hidden="true">↗</span></span></button>''' for i, project in enumerate(p['projects']))
html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#19191b"><title>{e(p['name'])} — Product designer</title><meta name="description" content="{e(p['intro'])} Explore selected fintech projects, design systems and the story behind the work."><meta property="og:title" content="{e(p['name'])} — Product designer"><meta property="og:description" content="Thoughtful design for complex products. A few projects, a little process, and the person behind them."><meta property="og:image" content="/reference/profile/ai-design-banner.png"><link rel="preload" href="/reference/profile/fonts/geist.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/reference/profile/fonts/caveat.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/reference/profile/home.css"><script src="/reference/profile/home.js" defer></script></head>
<body id="top" class="home-page"><a class="skip-link" href="#main">Skip to content</a><div class="reading-progress" aria-hidden="true"></div>
{navigation()}
<main id="main" class="page"><div class="section-rule"><span>[start here]</span><span class="rule-middle">a little corner of the internet</span><span>[hello, world]</span></div>
<section class="desk" aria-labelledby="hero-title"><div class="desk-lines" aria-hidden="true"></div><div class="hero-copy"><p class="hero-role">JUNIOR PRODUCT DESIGNER · KARBON BUSINESS</p><h1 id="hero-title" class="sticker">ajaymon</h1><p class="hero-position">{e(p['headline'])}</p><p class="hero-context">Customer dashboards, banking operations,<br>and the design systems behind them.</p><div class="hero-actions"><a class="button button-yellow" href="#work">See selected work ↓</a><a class="button" href="/reference/profile/AjaymonCV.pdf" target="_blank" rel="noopener">Résumé ↗</a></div><a class="hero-about" href="/about">From data engineering to product design ↗</a></div>
<div class="desk-objects"><img class="back-paper" src="/reference/profile/paperline/paper.png" alt="" aria-hidden="true"><section class="field-note" aria-label="Field notes"><button type="button" class="note-handle" aria-describedby="drag-help"><span class="handwritten">How I work</span><span aria-hidden="true">⠿</span></button><ol><li>Understand the workflow</li><li>Prototype the next step</li><li>Stay through design QA</li></ol><p id="drag-help">drag / arrow keys to move</p></section><figure class="polaroid tilt"><img src="/reference/profile/ajaymon-portrait.png" alt="Ajaymon, product designer" fetchpriority="high"><figcaption class="handwritten">↳ Bangalore, India</figcaption><span class="photo-doodle handwritten" aria-hidden="true">〰</span></figure></div></section>
<div class="desk-bottom"><span>[Bangalore, India]</span><button type="button" id="reset-note">reset the note ↺</button><a href="/contact">Get in touch ↗</a></div>
<section id="work" class="work-showcase" aria-labelledby="work-title"><div class="section-rule"><span>[selected work]</span><a class="work-all" href="/projects">All projects ↗</a></div><div class="work-heading"><h2 id="work-title">Complex products.<br><span>Clearer experiences.</span></h2><p>Fintech, AI &amp; the systems<br>that bring it all together.</p></div><div class="work-explorer"><div class="work-stage">{projects}</div><div class="work-picker" hidden><div class="work-picker-label"><span>Pick a project</span><span aria-hidden="true">↓</span></div><div class="work-tabs" aria-label="Selected projects">{work_tabs}</div><div class="work-picker-foot"><span class="work-position" aria-live="polite" aria-atomic="true">01 / {len(p['projects']):02d}</span><span>Explore the thinking behind it ↗</span></div></div></div></section>
<section class="collaborations reveal" aria-label="Career background"><div class="section-rule"><span>[the journey]</span><span>[so far]</span></div><div class="collaboration-content"><p class="handwritten">A journey from data engineering to product design.<br>These are the teams that shaped the way I work.</p><div class="company-names"><span>Karbon<span>product design</span></span><span>Skillto<span>UI / UX design</span></span><span>MBRDI <small>(EX)</small><span>data engineering</span></span></div><a class="handwritten" href="/about">and the story continues ↗</a></div></section>
<section class="details-section reveal" aria-labelledby="details-title"><div class="section-rule"><span>[closer look]</span><span>[the little things]</span></div><div class="details-heading"><h2 id="details-title" class="handwritten">It's all in the details.</h2><p>Click a frame. Take a closer look.</p></div><div class="details-grid">{gallery}</div></section>
<section class="contact-section reveal" aria-labelledby="contact-title"><div class="section-rule"><span>[still here?]</span><span>[let's make something]</span></div><span class="contact-star" aria-hidden="true">✳</span><h2 id="contact-title" class="handwritten">Your next idea.<br>Our next conversation.</h2><a class="button button-yellow" href="mailto:{e(p['email'])}">Say hello <span aria-hidden="true">↗</span></a><button class="copy-email" type="button" data-email="{e(p['email'])}">copy email <span aria-hidden="true">⧉</span></button><p class="copy-status" aria-live="polite"></p></section>
{footer()}</main>
<dialog class="image-dialog" aria-labelledby="image-title"><div class="dialog-bar"><h2 id="image-title">Design detail</h2><button type="button" class="close-dialog" aria-label="Close image">Close ×</button></div><img alt=""></dialog>
</body></html>'''
(root / 'src/reference/index.html').write_text(html)
print('Generated the reference-matched homepage.')
